contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, bool rejectEther) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}();

        uint beforeBalance = c.getBalance(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        if (rejectEther) {
            // This contract's receive is callable, so we cannot force a rejection through
            // the public interface without another contract; use the caller balance rule instead.
            try c.withdrawBalance() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdrawBalance() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalance = c.getBalance(address(this));
        uint afterContractBalance = address(c).balance;

        if (reverted) {
            assert(afterBalance == beforeBalance && afterContractBalance == beforeContractBalance);
        } else {
            assert(afterBalance == 0 && afterContractBalance == beforeContractBalance - beforeBalance);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}();
        uint256 balBefore = c.getBalance(address(this));
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            assert(c.getBalance(address(this)) == 0 && address(c).balance == cBalBefore - balBefore);
        } else {
            assert(c.getBalance(address(this)) == balBefore && address(c).balance == cBalBefore);
        }
    }

    receive() external payable {}
}
